-- Migration V4: interaction_event_journal
-- Task 02: stable Runtime Journal identity/range reads and durable HITL/Steer state.
-- The clean baseline applies this after V1-V2; version 3 is intentionally absent.

ALTER TABLE runtime_event ADD COLUMN event_schema_version TEXT NOT NULL DEFAULT '1';
ALTER TABLE runtime_event ADD COLUMN correlation_id TEXT;
ALTER TABLE runtime_event ADD COLUMN causation_id TEXT;

CREATE INDEX idx_runtime_event_run_sequence
ON runtime_event(run_id, sequence);

CREATE TABLE runtime_event_stream (
    run_id TEXT PRIMARY KEY,
    head_sequence INTEGER NOT NULL CHECK (head_sequence >= 0),
    earliest_sequence INTEGER NOT NULL CHECK (earliest_sequence >= 1),
    updated_at INTEGER NOT NULL CHECK (updated_at >= 0),
    FOREIGN KEY (run_id) REFERENCES run(run_id) ON DELETE CASCADE,
    CHECK (earliest_sequence <= head_sequence + 1)
) STRICT;

INSERT INTO runtime_event_stream(run_id, head_sequence, earliest_sequence, updated_at)
SELECT run_id, MAX(sequence), MIN(sequence), MAX(occurred_at)
FROM runtime_event
GROUP BY run_id;

ALTER TABLE interaction_request ADD COLUMN revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0);
ALTER TABLE interaction_request ADD COLUMN kind TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE interaction_request ADD COLUMN state TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (state IN ('PENDING', 'RESPONDED', 'APPLIED', 'EXPIRED', 'CANCELLED', 'INVALIDATED'));
ALTER TABLE interaction_request ADD COLUMN expiration_outcome TEXT NOT NULL DEFAULT 'FAIL_RUN'
    CHECK (expiration_outcome IN ('FAIL_RUN', 'CANCEL_RUN', 'RETURN_TO_AGENT'));
ALTER TABLE interaction_request ADD COLUMN state_reason_code TEXT;
ALTER TABLE interaction_request ADD COLUMN state_changed_at INTEGER;

UPDATE interaction_request
SET kind = CASE
        WHEN approval = 1 THEN 'approval'
        WHEN type IN ('clarification', 'confirmation', 'selection', 'input-required',
                      'artifact-review', 'conflict-resolution') THEN type
        ELSE 'unknown'
    END,
    expiration_outcome = CASE WHEN approval = 1 THEN 'CANCEL_RUN' ELSE 'FAIL_RUN' END,
    state = CASE
        WHEN EXISTS (
            SELECT 1 FROM interaction_application application
            WHERE application.request_id = interaction_request.request_id
              AND application.resolution_applied = 1
        ) THEN 'APPLIED'
        WHEN EXISTS (
            SELECT 1 FROM interaction_response response
            WHERE response.request_id = interaction_request.request_id
        ) THEN 'RESPONDED'
        ELSE 'PENDING'
    END,
    revision = CASE
        WHEN EXISTS (
            SELECT 1 FROM interaction_application application
            WHERE application.request_id = interaction_request.request_id
              AND application.resolution_applied = 1
        ) THEN 2
        WHEN EXISTS (
            SELECT 1 FROM interaction_response response
            WHERE response.request_id = interaction_request.request_id
        ) THEN 1
        ELSE 0
    END,
    state_changed_at = COALESCE(
        (SELECT application.applied_at FROM interaction_application application
         WHERE application.request_id = interaction_request.request_id
           AND application.resolution_applied = 1),
        (SELECT response.resolved_at FROM interaction_response response
         WHERE response.request_id = interaction_request.request_id)
    );

-- V1 permitted more than one unresolved request for a Run. Retain the newest and
-- invalidate older requests deterministically before adding the authoritative constraint.
UPDATE interaction_request
SET state = 'INVALIDATED',
    revision = revision + 1,
    state_reason_code = 'MIGRATION_SUPERSEDED_PENDING',
    state_changed_at = created_at
WHERE state = 'PENDING'
  AND EXISTS (
      SELECT 1
      FROM interaction_request newer
      WHERE newer.run_id = interaction_request.run_id
        AND newer.state = 'PENDING'
        AND (
            newer.created_at > interaction_request.created_at
            OR (newer.created_at = interaction_request.created_at
                AND newer.request_id > interaction_request.request_id)
        )
  );

CREATE UNIQUE INDEX uq_interaction_pending_per_run
ON interaction_request(run_id)
WHERE state = 'PENDING';

CREATE INDEX idx_interaction_due
ON interaction_request(state, expires_at, request_id);

ALTER TABLE interaction_response ADD COLUMN action TEXT NOT NULL DEFAULT 'submit';
ALTER TABLE interaction_response ADD COLUMN expected_revision INTEGER NOT NULL DEFAULT 0 CHECK (expected_revision >= 0);
ALTER TABLE interaction_response ADD COLUMN caller_scope TEXT NOT NULL DEFAULT '';
ALTER TABLE interaction_response ADD COLUMN canonical_digest TEXT NOT NULL DEFAULT '';
ALTER TABLE interaction_response ADD COLUMN responder_tenant_id TEXT NOT NULL DEFAULT '';
ALTER TABLE interaction_response ADD COLUMN responder_principal_id TEXT NOT NULL DEFAULT '';
ALTER TABLE interaction_response ADD COLUMN responder_principal_type TEXT NOT NULL DEFAULT '';
ALTER TABLE interaction_response ADD COLUMN receipt_status TEXT NOT NULL DEFAULT 'ACCEPTED'
    CHECK (receipt_status IN ('ACCEPTED', 'DUPLICATE', 'APPLIED'));

UPDATE interaction_response
SET action = CASE response_type
        WHEN 'APPROVE' THEN 'approve'
        WHEN 'REJECT' THEN 'reject'
        ELSE 'submit'
    END,
    caller_scope = (
        SELECT request.tenant_id || '|' || request.principal_type || '|' || request.principal_id
        FROM interaction_request request
        WHERE request.request_id = interaction_response.request_id
    ),
    responder_tenant_id = (
        SELECT request.tenant_id FROM interaction_request request
        WHERE request.request_id = interaction_response.request_id
    ),
    responder_principal_id = (
        SELECT request.principal_id FROM interaction_request request
        WHERE request.request_id = interaction_response.request_id
    ),
    responder_principal_type = (
        SELECT request.principal_type FROM interaction_request request
        WHERE request.request_id = interaction_response.request_id
    );

CREATE UNIQUE INDEX uq_interaction_response_idempotency
ON interaction_response(caller_scope, request_id, idempotency_key);

CREATE TABLE run_input (
    input_id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL,
    expected_run_version INTEGER,
    contents_schema_version TEXT NOT NULL,
    contents_payload BLOB NOT NULL,
    contents_hash TEXT NOT NULL,
    caller_scope TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    canonical_digest TEXT NOT NULL CHECK (length(canonical_digest) = 64),
    submitted_at INTEGER NOT NULL CHECK (submitted_at >= 0),
    accepted_at INTEGER NOT NULL CHECK (accepted_at >= submitted_at),
    status TEXT NOT NULL CHECK (status IN ('ACCEPTED', 'APPLIED', 'REJECTED')),
    applied_at INTEGER,
    attempt_id TEXT,
    iteration INTEGER,
    reason_code TEXT,
    FOREIGN KEY (run_id) REFERENCES run(run_id),
    FOREIGN KEY (attempt_id) REFERENCES execution_attempt(attempt_id),
    UNIQUE (caller_scope, run_id, idempotency_key),
    CHECK (expected_run_version IS NULL OR expected_run_version >= 0),
    CHECK (iteration IS NULL OR iteration >= 0),
    CHECK (
        (status = 'ACCEPTED' AND applied_at IS NULL AND attempt_id IS NULL AND iteration IS NULL)
        OR
        (status = 'APPLIED' AND applied_at IS NOT NULL AND attempt_id IS NOT NULL AND iteration IS NOT NULL)
        OR
        (status = 'REJECTED' AND reason_code IS NOT NULL)
    )
) STRICT;

CREATE INDEX idx_run_input_pending
ON run_input(run_id, status, accepted_at, input_id);

ALTER TABLE idempotency ADD COLUMN target_type TEXT;
ALTER TABLE idempotency ADD COLUMN target_id TEXT;
ALTER TABLE idempotency ADD COLUMN request_digest TEXT;
ALTER TABLE idempotency ADD COLUMN expires_at INTEGER;

-- Migration V5: sdk_conversation
-- Product-neutral Conversation Session index and command idempotency bindings.
-- Message bodies remain authoritative in the Runtime session_message table.

CREATE TABLE sdk_conversation (
    session_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    principal_id TEXT NOT NULL,
    principal_type TEXT NOT NULL,
    display_name TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 256),
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'ARCHIVED')),
    active_run_id TEXT,
    active_run_version INTEGER,
    active_dispatch_key TEXT,
    created_at INTEGER NOT NULL CHECK (created_at >= 0),
    last_activity_at INTEGER NOT NULL CHECK (last_activity_at >= created_at),
    revision INTEGER NOT NULL CHECK (revision >= 0),
    FOREIGN KEY (session_id) REFERENCES session(session_id),
    CHECK ((active_run_id IS NULL) = (active_run_version IS NULL)),
    CHECK (active_run_id IS NULL OR active_dispatch_key IS NULL)
) STRICT;

CREATE INDEX idx_sdk_conversation_scope_activity
ON sdk_conversation(
    tenant_id,
    principal_id,
    principal_type,
    status,
    last_activity_at DESC,
    session_id DESC
);

CREATE TABLE sdk_conversation_command (
    dispatch_key TEXT PRIMARY KEY,
    caller_scope_digest TEXT NOT NULL,
    operation TEXT NOT NULL,
    idempotency_key_digest TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    session_id TEXT NOT NULL,
    run_id TEXT,
    completed INTEGER NOT NULL CHECK (completed IN (0, 1)),
    result_revision INTEGER,
    created_at INTEGER NOT NULL CHECK (created_at >= 0),
    CHECK ((completed = 1) = (result_revision IS NOT NULL)),
    UNIQUE (caller_scope_digest, operation, idempotency_key_digest)
) STRICT;

CREATE INDEX idx_sdk_conversation_command_session
ON sdk_conversation_command(session_id, created_at);

-- Migration V6: memory_foundation
CREATE TABLE memory_candidate (
    candidate_id TEXT PRIMARY KEY NOT NULL,
    request_key_digest TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    owner_id TEXT NOT NULL,
    scope_type TEXT NOT NULL,
    target_id TEXT NOT NULL,
    visibility TEXT NOT NULL,
    security_label_bits INTEGER NOT NULL,
    kind TEXT NOT NULL,
    subject_key TEXT NOT NULL,
    normalized_digest TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
    revision INTEGER NOT NULL CHECK (revision >= 0),
    updated_at INTEGER NOT NULL,
    payload_schema_version INTEGER NOT NULL CHECK (payload_schema_version = 1),
    payload_type TEXT NOT NULL CHECK (payload_type = 'memory-candidate'),
    payload_hash TEXT NOT NULL,
    payload BLOB NOT NULL,
    UNIQUE (tenant_id, owner_id, scope_type, target_id, visibility, request_key_digest)
) STRICT;

CREATE INDEX idx_memory_candidate_scope_page
    ON memory_candidate(tenant_id, owner_id, scope_type, target_id, visibility, updated_at DESC, candidate_id DESC);
CREATE INDEX idx_memory_candidate_pending_subject
    ON memory_candidate(
        tenant_id, owner_id, scope_type, target_id, visibility, kind, normalized_digest, subject_key)
    WHERE status = 'PENDING';

CREATE TABLE memory_record (
    memory_id TEXT NOT NULL,
    memory_version INTEGER NOT NULL CHECK (memory_version > 0),
    tenant_id TEXT NOT NULL,
    owner_id TEXT NOT NULL,
    scope_type TEXT NOT NULL,
    target_id TEXT NOT NULL,
    visibility TEXT NOT NULL,
    security_label_bits INTEGER NOT NULL,
    kind TEXT NOT NULL,
    subject_key TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'INVALIDATED')),
    normalized_digest TEXT NOT NULL,
    updated_at INTEGER NOT NULL,
    payload_schema_version INTEGER NOT NULL CHECK (payload_schema_version = 1),
    payload_type TEXT NOT NULL CHECK (payload_type = 'memory-record'),
    payload_hash TEXT NOT NULL,
    payload BLOB NOT NULL,
    PRIMARY KEY (memory_id, memory_version)
) STRICT;

CREATE UNIQUE INDEX uq_memory_record_active_id
    ON memory_record(memory_id) WHERE status = 'ACTIVE';
CREATE UNIQUE INDEX uq_memory_record_active_subject
    ON memory_record(tenant_id, owner_id, scope_type, target_id, visibility, kind, subject_key)
    WHERE status = 'ACTIVE';
CREATE INDEX idx_memory_record_scope_page
    ON memory_record(tenant_id, owner_id, scope_type, target_id, visibility, updated_at DESC, memory_id DESC, memory_version DESC);

CREATE TABLE memory_audit_event (
    event_id INTEGER PRIMARY KEY AUTOINCREMENT,
    operation TEXT NOT NULL,
    candidate_id TEXT,
    memory_id TEXT,
    memory_version INTEGER,
    tenant_id TEXT NOT NULL,
    owner_id TEXT NOT NULL,
    scope_type TEXT NOT NULL,
    target_id TEXT NOT NULL,
    visibility TEXT NOT NULL,
    actor_id TEXT NOT NULL,
    safe_attributes_json TEXT NOT NULL,
    occurred_at INTEGER NOT NULL,
    idempotency_key_digest TEXT,
    request_digest TEXT,
    candidate_revision INTEGER,
    CHECK ((idempotency_key_digest IS NULL) = (request_digest IS NULL))
) STRICT;

CREATE UNIQUE INDEX uq_memory_audit_idempotency
    ON memory_audit_event(
        tenant_id, owner_id, scope_type, target_id, visibility, operation, idempotency_key_digest)
    WHERE idempotency_key_digest IS NOT NULL;
CREATE INDEX idx_memory_audit_scope_time
    ON memory_audit_event(tenant_id, owner_id, scope_type, target_id, visibility, occurred_at);

-- Migration V7: artifact_foundation
CREATE TABLE artifact (
    artifact_id TEXT NOT NULL,
    artifact_version INTEGER NOT NULL,
    artifact_type TEXT NOT NULL,
    title TEXT NOT NULL,
    payload_id TEXT NOT NULL,
    payload_sha256 TEXT NOT NULL,
    payload_byte_count INTEGER NOT NULL,
    payload_media_type TEXT NOT NULL,
    project_id TEXT NOT NULL,
    workspace_ref TEXT NOT NULL,
    run_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    file_change_set_ref TEXT,
    execution_ref TEXT,
    source_logical_path TEXT NOT NULL,
    source_hash TEXT NOT NULL,
    export_policy TEXT NOT NULL,
    created_by_id TEXT NOT NULL,
    created_by_type TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at_ms INTEGER NOT NULL,
    PRIMARY KEY(artifact_id, artifact_version),
    UNIQUE(payload_id),
    CHECK(artifact_version >= 1),
    CHECK(payload_byte_count >= 0),
    CHECK(status IN ('PUBLISHED','REVOKED'))
);
CREATE INDEX ix_artifact_project_created ON artifact(project_id, created_at_ms, artifact_id);

-- Migration V8: tool_reconciliation_evidence
ALTER TABLE tool_journal ADD COLUMN dispatch_execution_id TEXT;
ALTER TABLE tool_journal ADD COLUMN dispatch_process_id INTEGER;
ALTER TABLE tool_journal ADD COLUMN dispatch_workdir_digest TEXT;
ALTER TABLE tool_journal ADD COLUMN reconcile_status TEXT;
ALTER TABLE tool_journal ADD COLUMN reconcile_reason TEXT;

CREATE INDEX idx_tool_journal_dispatch_execution
ON tool_journal(dispatch_execution_id)
WHERE dispatch_execution_id IS NOT NULL;

-- Migration V9: optional_interaction_expiry
-- Human interactions may remain pending until answered or explicitly cancelled.
-- Existing requests retain their configured deadline.

DROP INDEX idx_interaction_request_pending;
DROP INDEX idx_interaction_due;

ALTER TABLE interaction_request ADD COLUMN expires_at_v9 INTEGER
    CHECK (expires_at_v9 IS NULL OR expires_at_v9 > created_at);
UPDATE interaction_request SET expires_at_v9 = expires_at;
ALTER TABLE interaction_request DROP COLUMN expires_at;
ALTER TABLE interaction_request RENAME COLUMN expires_at_v9 TO expires_at;

CREATE INDEX idx_interaction_request_pending
ON interaction_request(run_id, expires_at, created_at);

CREATE INDEX idx_interaction_due
ON interaction_request(state, expires_at, request_id)
WHERE expires_at IS NOT NULL;

-- Migration V10: human_wait_timing
ALTER TABLE run
ADD COLUMN accumulated_human_wait_millis INTEGER NOT NULL DEFAULT 0
CHECK (accumulated_human_wait_millis >= 0);

ALTER TABLE run
ADD COLUMN human_wait_started_at INTEGER
CHECK (human_wait_started_at IS NULL OR human_wait_started_at >= created_at);

-- Older schemas did not record when a human wait began. Start accounting from
-- migration time without inventing an unverified historical paused duration.
UPDATE run
SET human_wait_started_at = updated_at
WHERE status IN ('WAITING_INTERACTION', 'WAITING_APPROVAL');

-- Migration V11: separate_run_limits
ALTER TABLE run
ADD COLUMN limit_max_tool_calls INTEGER NOT NULL DEFAULT 0
CHECK (limit_max_tool_calls >= 0);

ALTER TABLE run
ADD COLUMN limit_max_model_calls INTEGER NOT NULL DEFAULT 1
CHECK (limit_max_model_calls > 0);

ALTER TABLE run
ADD COLUMN limit_max_child_runs INTEGER NOT NULL DEFAULT 0
CHECK (limit_max_child_runs >= 0);

-- Before this migration, the three budget columns also stored the corresponding
-- run limits. Preserve those limits and recover the real frozen budget values
-- from the content-addressed configuration snapshot.
UPDATE run
SET limit_max_tool_calls = budget_max_tool_calls,
    limit_max_model_calls = budget_max_model_calls,
    limit_max_child_runs = budget_max_child_runs,
    budget_max_tool_calls = COALESCE(
        (SELECT CAST(json_extract(CAST(content_payload AS TEXT), '$.budget.maxToolCalls') AS INTEGER)
         FROM configuration_snapshot
         WHERE configuration_ref = run.configuration_ref),
        budget_max_tool_calls),
    budget_max_model_calls = COALESCE(
        (SELECT CAST(json_extract(CAST(content_payload AS TEXT), '$.budget.maxModelCalls') AS INTEGER)
         FROM configuration_snapshot
         WHERE configuration_ref = run.configuration_ref),
        budget_max_model_calls),
    budget_max_child_runs = COALESCE(
        (SELECT CAST(json_extract(CAST(content_payload AS TEXT), '$.budget.maxChildRuns') AS INTEGER)
         FROM configuration_snapshot
         WHERE configuration_ref = run.configuration_ref),
        budget_max_child_runs);

