);

CREATE INDEX idx_coding_session_event_cursor_run
    ON coding_session_event_cursor(run_id, exclusive_sequence);

-- Migration V1003: coding_session_management
ALTER TABLE coding_session_activity
    ADD COLUMN session_status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (session_status IN ('ACTIVE', 'ARCHIVED', 'CLOSED', 'DELETED'));

